// Z-Anatomy whole-body presets. Patterns match structure or group names; `within` limits them to
// body systems, `also` adds [patterns, systems] pairs, `context` lists systems ghosted for orientation.
const SK = 'Skeletal system', JT = 'Joints', MU = 'Muscular system', CV = 'Cardiovascular system',
  NV = 'Nervous system & Sense organs', VI = 'Visceral systems';
const HEART = ['^heart', '^(left|right) (atrium|ventricle)$', 'auricle', 'valve', 'cusp', 'papillary', 'chordae', 'septum'];

// Colours for the whole-body model (Z-Anatomy's own colours live in shader nodes that do not
// export). First matching rule wins; tested against "system / group / … / structure name".
const BODY_COLOR_RULES = [
  [/^Skeletal system.*(teeth|tooth|incisor|canine|premolar|molar)/i, '#f3efe2'],
  [/^Skeletal system.*cartilage/i, '#9fc4d6'],
  [/^Skeletal system/i, '#e6dac0'],
  [/^Joints.*(menisc|cartilage|disc|labrum|anulus|nucleus pulposus)/i, '#8fc0dc'],
  [/^Joints.*bursa/i, '#a8d4ea'],
  [/^Joints.*capsule/i, '#cbb994'],
  [/^Joints/i, '#d8c99a'],
  [/^Muscular system.*(fascia|aponeuro|tendon|retinacul|sheath)/i, '#e2d6bb'],
  [/^Muscular system/i, '#b5443c'],
  [/^Cardiovascular system.*(pulmonary arter|pulmonary trunk)/i, '#4a6fd0'],
  [/^Cardiovascular system.*pulmonary vein/i, '#d33b3b'],
  [/^Cardiovascular system.*\/ heart \/|^Cardiovascular system.*(atrium|ventricle|valve|cusp|papillary|chordae|auricle|septum)/i, '#b8504a'],
  [/^Cardiovascular system \/ Venous/i, '#3f66c8'],
  [/^Cardiovascular system/i, '#d33b3b'],
  [/^Lymphoid organs.*(spleen)/i, '#7b3352'],
  [/^Lymphoid organs.*(thymus)/i, '#c9a0a8'],
  [/^Lymphoid organs/i, '#8cc46b'],
  [/^Nervous system.*Peripheral/i, '#f2cf45'],
  [/^Nervous system.*(spinal cord|cauda|nerve|rootlet|root of)/i, '#f2cf45'],
  [/^Nervous system.*Sense organs/i, '#e9e4dc'],
  [/^Visceral systems.*liver/i, '#8e3b2c'],
  [/^Visceral systems.*gallbladder|^Visceral systems.*bile/i, '#5c8f3c'],
  [/^Visceral systems.*pancrea/i, '#e3bf6a'],
  [/^Visceral systems.*(lung|pleura)/i, '#e9a3ab'],
  [/^Visceral systems.*(trachea|bronch|laryn|cartilage|epiglott)/i, '#cfe1ea'],
  [/^Visceral systems.*kidney|^Visceral systems.*renal/i, '#9b3e3a'],
  [/^Visceral systems.*(ureter|urinary bladder|urethra)/i, '#e2b277'],
  [/^Visceral systems.*(thyroid|parathyroid|suprarenal|adrenal|pituitary|endocrine)/i, '#b85a4f'],
  [/^Visceral systems.*(tongue)/i, '#c9605a'],
  [/^Visceral systems/i, '#e0a08c'],
];
export function bodyColor(path) {
  for (const [re, c] of BODY_COLOR_RULES) if (re.test(path)) return c;
  return null;
}

// Cardiac conduction presets: the schematic conduction overlay (conduction.js) inside a see-through heart,
// with an animated impulse (`rhythm`). Red = blocked, orange = slowed / muscle-to-muscle spread.
const RED = '#ff2d2d', ORANGE = '#ff9f2f';
const plain = (re) => re.replace(/\\/g, '');
const cond = (id, zh, en, { blocked = [], slow = [], sick = [], spread = [], note, ekg }) => ({
  id, zh, en, view: 'iso-left', frame: 'ghost', within: [CV], rhythm: id,
  show: ['Cardiac conduction system', ...spread.map((s) => `^Slow spread to ${s}$`)],
  ghost: [[['^Heart$'], [CV]]],
  // colour rules are tested against the full path ("… / Right bundle branch"), hence "/ name$"
  color: [
    ...blocked.map((b) => [`/ ${b}$`, RED, `阻滯 Blocked: ${plain(b)}`]),
    ...slow.map((s) => [`/ ${s}$`, ORANGE, `傳導變慢 Slowed: ${plain(s)}`]),
    ...sick.map((s) => [`/ ${s}$`, ORANGE, `病變處 Diseased: ${plain(s)}`]),
    ...(spread.length ? [['Slow spread', ORANGE, '心肌間緩慢傳導 Slow muscle-to-muscle spread']] : []),
  ],
  note, ekg,
});
const CONDUCTION = [
  cond('normal', '正常傳導路徑', 'Normal conduction', {
    note: '竇房結 → 心房（P 波）→ 房室結延遲（PR 間期）→ 希氏束 → 左右束支 → 浦金埃纖維 → 心室收縮（QRS）。動畫為慢動作。SA node → atria (P wave) → AV-node delay (PR interval) → His bundle → bundle branches → Purkinje fibres → ventricles (QRS). Animation is slowed down.',
    ekg: 'PR 0.12–0.20 s · QRS < 0.12 s' }),
  cond('av1', '一度房室傳導阻滯', '1st-degree AV block', { slow: ['Atrioventricular \\(AV\\) node'],
    note: '每個訊號都能通過房室結，只是比較慢。通常無症狀。Every impulse gets through the AV node, just slowly. Usually harmless.',
    ekg: 'PR > 0.20 s，每個 P 波後都有 QRS。PR > 0.20 s, every P followed by a QRS.' }),
  cond('wenck', '二度一型（文氏）', '2nd-degree AV block, Mobitz I (Wenckebach)', { slow: ['Atrioventricular \\(AV\\) node'],
    note: '房室結越來越疲乏，延遲逐次變長，直到有一次訊號過不去（漏跳），然後重來。阻滯通常在房室結，多屬良性。The AV node tires: each delay is longer until one beat is dropped, then the cycle restarts. Usually at the AV node and benign.',
    ekg: 'PR 逐漸延長 → 一個 P 波後沒有 QRS。Progressive PR lengthening, then a dropped QRS.' }),
  cond('mobitz2', '二度二型（Mobitz II）', '2nd-degree AV block, Mobitz II', { sick: ['Bundle of His'],
    note: '阻滯在希氏束或更下方：PR 固定，卻突然漏跳。可能惡化為完全阻滯，常需心律調節器。Block at or below the His bundle: fixed PR, then a sudden dropped beat. Can progress to complete block; often needs a pacemaker.',
    ekg: 'PR 固定不變，偶有 P 波後無 QRS；QRS 常變寬。Constant PR with sudden dropped QRS; QRS often wide.' }),
  cond('chb', '三度（完全）房室傳導阻滯', '3rd-degree (complete) heart block', { blocked: ['Atrioventricular \\(AV\\) node'],
    note: '心房的訊號完全無法傳到心室；心室靠下方的「備用節律點」自己跳，速度很慢（本例約 38 次/分）。會頭暈、昏倒，需要心律調節器。No atrial impulse reaches the ventricles; a slow back-up pacemaker below the block drives them (here ~38/min). Causes dizziness or fainting; needs a pacemaker.',
    ekg: 'P 波與 QRS 各跳各的（房室分離），心室速率慢。P waves and QRS complexes are unrelated (AV dissociation); slow ventricular rate.' }),
  cond('rbbb', '右束支傳導阻滯', 'Right bundle branch block (RBBB)', { blocked: ['Right bundle branch'], spread: ['right ventricle'],
    note: '右束支不通，右心室要等左邊的訊號穿過中膈「慢慢走過來」，所以右心室較晚收縮。可見於健康人，也見於肺部或心臟疾病。The right ventricle is reached late, cell-to-cell through the septum from the left. Can be normal, or due to lung or heart disease.',
    ekg: 'QRS ≥ 0.12 s；V1 呈 rSR′（兔耳）；I、V6 寬而模糊的 S 波。QRS ≥ 0.12 s; rSR′ in V1; wide slurred S in I and V6.' }),
  cond('lbbb', '左束支傳導阻滯', 'Left bundle branch block (LBBB)', { blocked: ['Left bundle branch'], spread: ['left ventricle'],
    note: '左束支不通，左心室由右往左慢慢被激動，左心室收縮不同步。新發生時要排除心肌梗塞；常見於高血壓、心肌病變。The left ventricle is activated late, right to left, so it contracts out of sync. New LBBB needs heart-attack work-up; common with hypertension or cardiomyopathy.',
    ekg: 'QRS ≥ 0.12 s；V1 深而寬的 QS/rS；I、aVL、V5–V6 寬而有缺口的 R 波。QRS ≥ 0.12 s; broad deep S in V1; broad notched R in I, aVL, V5–V6.' }),
  cond('lafb', '左前分支阻滯', 'Left anterior fascicular block (LAFB)', { blocked: ['Left anterior fascicle'], spread: ['anterior left ventricle'],
    note: '左前分支細長最易受損；左心室前上壁改由後分支繞過去激動，電軸因此左偏。QRS 通常不寬。The thin anterior fascicle is easily damaged; the anterior-superior wall is reached via the posterior fascicle, swinging the axis to the left. QRS usually stays narrow.',
    ekg: '電軸左偏（−45° 以上）；I、aVL 呈 qR，II、III、aVF 呈 rS。Left axis deviation (≤ −45°); qR in I/aVL, rS in II/III/aVF.' }),
  cond('lpfb', '左後分支阻滯', 'Left posterior fascicular block (LPFB)', { blocked: ['Left posterior fascicle'], spread: ['inferior left ventricle'],
    note: '左後分支短而粗、血流供應雙重，單獨阻滯少見，出現時常表示較廣泛的心臟疾病。下壁改由前分支繞行激動，電軸右偏。The broad, doubly supplied posterior fascicle is rarely blocked alone; when it is, heart disease is usually extensive. The inferior wall is reached via the anterior fascicle (right axis).',
    ekg: '電軸右偏（+90° 以上，需排除右心室肥大等）；I、aVL 呈 rS，III、aVF 呈 qR。Right axis deviation (≥ +90°, other causes excluded); rS in I/aVL, qR in III/aVF.' }),
  cond('bifasc', '雙分支阻滯', 'Bifascicular block (RBBB + LAFB)', { blocked: ['Right bundle branch', 'Left anterior fascicle'], spread: ['right ventricle', 'anterior left ventricle'],
    note: '三條傳導分支（右束支、左前分支、左後分支）中兩條不通，心室只剩左後分支這一條路。若最後一條也壞掉就會變成完全阻滯；有昏厥症狀時需評估心律調節器。Two of the three fascicles are blocked; the ventricles depend on the left posterior fascicle alone. Fainting spells need pacemaker evaluation.',
    ekg: 'RBBB 圖形 + 電軸左偏（LAFB）。（RBBB + LPFB 亦屬雙分支阻滯。）RBBB pattern plus left axis deviation. (RBBB + LPFB also counts.)' }),
  cond('trifasc', '三分支阻滯', 'Trifascicular block (bifascicular + 1st-degree AV block)', {
    blocked: ['Right bundle branch', 'Left anterior fascicle'], slow: ['Atrioventricular \\(AV\\) node'], spread: ['right ventricle', 'anterior left ventricle'],
    note: '雙分支阻滯再加上 PR 延長：表示剩下的傳導路（左後分支或房室結）也已變慢。真正的三分支阻滯則是左右束支交替阻滯。容易進展為完全阻滯。Bifascicular block plus a long PR: the remaining route is also slow. (True trifascicular block = alternating bundle branch block.) High risk of complete heart block.',
    ekg: 'RBBB + 電軸左偏 + PR > 0.20 s。RBBB + left axis deviation + PR > 0.20 s.' }),
];

